SELECT JSON_EXTRACT(props, '$.archetype') FROM anchors WHERE id = ?
SELECT id, arch_type, props FROM ( (SELECT m.id, m.creation_date AS ord, m.tie_id AS tie, m.arch_type, m.props FROM jac_snb_message_mirror m WHERE m.creator_id = ? AND m.arch_type = ? AND m.creation_date <= ? ORDER BY m.creation_date DESC, m.tie_id ASC LIMIT 10) UNION ALL (SELECT m.id, m.creation_date AS ord, m.tie_id AS tie, m.arch_type, m.props FROM jac_snb_message_mirror m WHERE m.creator_id = ? AND m.arch_type = ? AND m.creation_date <= ? ORDER BY m.creation_date DESC, m.tie_id ASC LIMIT 10) ) u ORDER BY ord DESC, tie ASC LIMIT 10
SELECT m.id, m.root_of_replyof, p.props FROM jac_snb_message_mirror m JOIN anchors p ON p.id = m.root_of_replyof WHERE m.id IN (?, ?) AND m.root_of_replyof IS NOT NULL
SELECT e.src, n.props FROM anchors e JOIN anchors n ON n.id = e.dst AND n.kind = 'NodeAnchor' WHERE e.kind = 'EdgeAnchor' AND e.arch_type = 'HasCreator' AND e.src IN (?, ?) ORDER BY e.seq, e.id
